import { sql } from "drizzle-orm";
import {
  bigserial,
  boolean,
  date,
  doublePrecision,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  real,
  serial,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core";

/*
 * napfdeal data model (Phase 1).
 * Money is stored in integer cents (EUR). Times are timestamptz.
 * Migrations are generated by drizzle-kit (CI job "prepare"), never written by hand.
 */

const ts = (name: string) => timestamp(name, { withTimezone: true });

// ---------------------------------------------------------------------------
// Settings (job schedules, thresholds; editable in /admin later)
// ---------------------------------------------------------------------------
export const appSetting = pgTable("app_setting", {
  key: text("key").primaryKey(),
  value: jsonb("value").notNull(),
  updatedAt: ts("updated_at").notNull().defaultNow(),
});

// ---------------------------------------------------------------------------
// Sources
// ---------------------------------------------------------------------------
export const network = pgTable("network", {
  id: serial("id").primaryKey(),
  /** awin, tradedoubler, daisycon, amazon, awin-test */
  slug: text("slug").notNull().unique(),
  name: text("name").notNull(),
  /** Test data network: never shown publicly unless SHOW_TEST_DATA=1. */
  isTest: boolean("is_test").notNull().default(false),
  createdAt: ts("created_at").notNull().defaultNow(),
});

export const shop = pgTable(
  "shop",
  {
    id: serial("id").primaryKey(),
    networkId: integer("network_id")
      .notNull()
      .references(() => network.id),
    /** Advertiser/programme id in the network */
    externalId: text("external_id").notNull(),
    name: text("name").notNull(),
    /** de | at */
    country: text("country").notNull(),
    enabled: boolean("enabled").notNull().default(true),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [uniqueIndex("shop_network_external_country_uq").on(t.networkId, t.externalId, t.country)],
);

export const feed = pgTable(
  "feed",
  {
    id: serial("id").primaryKey(),
    networkId: integer("network_id")
      .notNull()
      .references(() => network.id),
    shopId: integer("shop_id")
      .notNull()
      .references(() => shop.id),
    externalId: text("external_id").notNull(),
    name: text("name").notNull(),
    country: text("country").notNull(),
    language: text("language"),
    /** Opaque "last updated" marker from the network (e.g. Awin "Last Imported"); change = new data */
    remoteVersion: text("remote_version"),
    /** remoteVersion at our last successful import */
    importedVersion: text("imported_version"),
    lastImportAt: ts("last_import_at"),
    enabled: boolean("enabled").notNull().default(true),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [uniqueIndex("feed_network_external_uq").on(t.networkId, t.externalId)],
);

export const feedImportRun = pgTable(
  "feed_import_run",
  {
    id: serial("id").primaryKey(),
    networkId: integer("network_id").references(() => network.id),
    feedId: integer("feed_id").references(() => feed.id, { onDelete: "set null" }),
    /** full | check | manual */
    trigger: text("trigger").notNull(),
    /** running | ok | failed | skipped */
    status: text("status").notNull().default("running"),
    startedAt: ts("started_at").notNull().defaultNow(),
    finishedAt: ts("finished_at"),
    rowsTotal: integer("rows_total").notNull().default(0),
    rowsSkipped: integer("rows_skipped").notNull().default(0),
    offersCreated: integer("offers_created").notNull().default(0),
    offersUpdated: integer("offers_updated").notNull().default(0),
    offersDeactivated: integer("offers_deactivated").notNull().default(0),
    productsCreated: integer("products_created").notNull().default(0),
    priceChanges: integer("price_changes").notNull().default(0),
    suspects: integer("suspects").notNull().default(0),
    reviewItems: integer("review_items").notNull().default(0),
    errors: integer("errors").notNull().default(0),
    /** Technical message only – never personal data */
    errorMessage: text("error_message"),
  },
  (t) => [index("feed_import_run_feed_started_idx").on(t.feedId, t.startedAt)],
);

// ---------------------------------------------------------------------------
// Catalogue
// ---------------------------------------------------------------------------
export const category = pgTable(
  "category",
  {
    id: serial("id").primaryKey(),
    /** "hund" or "hund/trockenfutter" */
    path: text("path").notNull().unique(),
    slug: text("slug").notNull(),
    name: text("name").notNull(),
    parentId: integer("parent_id"),
    note: text("note"),
    sortOrder: integer("sort_order").notNull().default(0),
    enabled: boolean("enabled").notNull().default(true),
  },
  (t) => [index("category_parent_idx").on(t.parentId)],
);

export const product = pgTable(
  "product",
  {
    id: serial("id").primaryKey(),
    slug: text("slug").notNull().unique(),
    name: text("name").notNull(),
    brand: text("brand"),
    /** Folded brand for fuzzy candidate lookups */
    brandNorm: text("brand_norm"),
    /** Animal-level or subcategory; null = needs review */
    categoryId: integer("category_id").references(() => category.id),
    /** auto | review | manual */
    categoryStatus: text("category_status").notNull().default("auto"),
    sizeCount: integer("size_count"),
    sizeAmount: doublePrecision("size_amount"),
    /** g | kg | ml | l | stk */
    sizeUnit: text("size_unit"),
    /** Total in base unit */
    sizeTotal: doublePrecision("size_total"),
    /** kg | l | stk */
    sizeBaseUnit: text("size_base_unit"),
    sizeLabel: text("size_label"),
    /** feed | title | manual */
    sizeSource: text("size_source"),
    /** ok | review | none */
    sizeStatus: text("size_status").notNull().default("none"),
    /** Image URL from an allowed feed (served via our own proxy /img/p/[id], never hot-linked) */
    imageUrl: text("image_url"),
    /** Created from a test network; hidden publicly, deleted when test mode is off */
    isTest: boolean("is_test").notNull().default(false),
    createdAt: ts("created_at").notNull().defaultNow(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [index("product_brand_norm_idx").on(t.brandNorm), index("product_category_idx").on(t.categoryId)],
);

export const productGtin = pgTable(
  "product_gtin",
  {
    /** GTIN-14, zero-padded */
    gtin: text("gtin").primaryKey(),
    productId: integer("product_id")
      .notNull()
      .references(() => product.id, { onDelete: "cascade" }),
  },
  (t) => [index("product_gtin_product_idx").on(t.productId)],
);

// ---------------------------------------------------------------------------
// Offers and prices
// ---------------------------------------------------------------------------
export const offer = pgTable(
  "offer",
  {
    id: serial("id").primaryKey(),
    shopId: integer("shop_id")
      .notNull()
      .references(() => shop.id),
    feedId: integer("feed_id").references(() => feed.id, { onDelete: "set null" }),
    /** null = not assigned yet (waiting in match_review) */
    productId: integer("product_id").references(() => product.id, { onDelete: "set null" }),
    externalId: text("external_id").notNull(),
    country: text("country").notNull(),
    title: text("title").notNull(),
    brand: text("brand"),
    gtins: text("gtins").array().notNull().default(sql`'{}'::text[]`),
    priceCents: integer("price_cents").notNull(),
    shippingCents: integer("shipping_cents"),
    currency: text("currency").notNull().default("EUR"),
    /** Price per kg / l / piece in cents, based on the product's pack size */
    unitPriceCents: integer("unit_price_cents"),
    available: boolean("available").notNull().default(true),
    /** Affiliate deeplink – only ever used by /go/[offerId] */
    deeplink: text("deeplink").notNull(),
    imageUrl: text("image_url"),
    feedCategory: text("feed_category"),
    /** Still present in the latest import of its feed */
    active: boolean("active").notNull().default(true),
    /** Big one-step drop, not yet confirmed → not shown as deal */
    priceSuspect: boolean("price_suspect").notNull().default(false),
    checkedAt: ts("checked_at").notNull(),
    priceChangedAt: ts("price_changed_at").notNull(),
    lastHistoryAt: ts("last_history_at"),
    firstSeenAt: ts("first_seen_at").notNull().defaultNow(),
    lastSeenAt: ts("last_seen_at").notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("offer_shop_external_uq").on(t.shopId, t.externalId),
    index("offer_product_country_idx").on(t.productId, t.country),
    index("offer_feed_seen_idx").on(t.feedId, t.lastSeenAt),
  ],
);

/** Written only on change + one anchor per calendar day (Europe/Vienna). */
export const priceHistory = pgTable(
  "price_history",
  {
    id: bigserial("id", { mode: "number" }).primaryKey(),
    offerId: integer("offer_id")
      .notNull()
      .references(() => offer.id, { onDelete: "cascade" }),
    priceCents: integer("price_cents").notNull(),
    shippingCents: integer("shipping_cents"),
    available: boolean("available").notNull(),
    /** Excluded from statistics until confirmed */
    suspect: boolean("suspect").notNull().default(false),
    /** first | change | anchor | gone */
    kind: text("kind").notNull(),
    recordedAt: ts("recorded_at").notNull().defaultNow(),
  },
  (t) => [index("price_history_offer_time_idx").on(t.offerId, t.recordedAt)],
);

// ---------------------------------------------------------------------------
// Admin review queue
// ---------------------------------------------------------------------------
export const matchReview = pgTable(
  "match_review",
  {
    id: serial("id").primaryKey(),
    /** match (offer without GTIN, similar product found) | size | category */
    kind: text("kind").notNull(),
    offerId: integer("offer_id").references(() => offer.id, { onDelete: "cascade" }),
    productId: integer("product_id").references(() => product.id, { onDelete: "cascade" }),
    candidateProductId: integer("candidate_product_id").references(() => product.id, { onDelete: "cascade" }),
    score: real("score"),
    details: jsonb("details"),
    /** open | accepted | rejected */
    status: text("status").notNull().default("open"),
    createdAt: ts("created_at").notNull().defaultNow(),
    resolvedAt: ts("resolved_at"),
  },
  (t) => [
    uniqueIndex("match_review_open_offer_uq")
      .on(t.kind, t.offerId)
      .where(sql`status = 'open' and offer_id is not null`),
    uniqueIndex("match_review_open_product_uq")
      .on(t.kind, t.productId)
      .where(sql`status = 'open' and product_id is not null`),
    index("match_review_status_idx").on(t.status, t.kind),
  ],
);

// ---------------------------------------------------------------------------
// Statistics (recomputed by the worker after imports)
// ---------------------------------------------------------------------------

/** Best total price (price + shipping) per product, country and calendar day (Europe/Vienna). */
export const productDaily = pgTable(
  "product_daily",
  {
    productId: integer("product_id")
      .notNull()
      .references(() => product.id, { onDelete: "cascade" }),
    country: text("country").notNull(),
    day: date("day", { mode: "string" }).notNull(),
    bestCents: integer("best_cents").notNull(),
    offerCount: integer("offer_count").notNull(),
  },
  (t) => [primaryKey({ columns: [t.productId, t.country, t.day] })],
);

/** Current numbers per product and country for lists, deals and "lowest since" notes. */
export const productStats = pgTable(
  "product_stats",
  {
    productId: integer("product_id")
      .notNull()
      .references(() => product.id, { onDelete: "cascade" }),
    country: text("country").notNull(),
    /** Cheapest available, non-suspect total right now */
    bestCents: integer("best_cents").notNull(),
    bestOfferId: integer("best_offer_id").notNull(),
    bestUnitPriceCents: integer("best_unit_price_cents"),
    offerCount: integer("offer_count").notNull(),
    /** Median of daily best totals of the last 30 days (before today) */
    median30Cents: integer("median30_cents"),
    /** Days with data in the last 30 days (before today) */
    days30: integer("days30").notNull().default(0),
    /** Best total of the most recent earlier day */
    prevBestCents: integer("prev_best_cents"),
    prevBestDay: date("prev_best_day", { mode: "string" }),
    min90Cents: integer("min90_cents"),
    /** Days since the last day that was cheaper than now; null = never cheaper */
    lowestSinceDays: integer("lowest_since_days"),
    /** Days with data before today */
    historyDays: integer("history_days").notNull().default(0),
    checkedAt: timestamp("checked_at", { withTimezone: true }).notNull(),
    computedAt: timestamp("computed_at", { withTimezone: true }).notNull(),
  },
  (t) => [primaryKey({ columns: [t.productId, t.country] }), index("product_stats_country_idx").on(t.country)],
);

/** Outgoing clicks, aggregated per day. No IP address, no user id, no cookie. */
export const clickStat = pgTable(
  "click_stat",
  {
    day: date("day", { mode: "string" }).notNull(),
    offerId: integer("offer_id")
      .notNull()
      .references(() => offer.id, { onDelete: "cascade" }),
    country: text("country").notNull(),
    /** web | mail | discord | push | pinterest | telegram … (from utm_source, whitelisted) */
    source: text("source").notNull(),
    clicks: integer("clicks").notNull().default(0),
  },
  (t) => [primaryKey({ columns: [t.day, t.offerId, t.source] })],
);

// ---------------------------------------------------------------------------
// Accounts (tables in the shape Better Auth expects; keys = model field names)
// ---------------------------------------------------------------------------
export const user = pgTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").notNull().default(false),
  image: text("image"),
  /** de | at – preferred country edition */
  country: text("country"),
  /** user | admin */
  role: text("role").notNull().default("user"),
  createdAt: ts("created_at").notNull().defaultNow(),
  updatedAt: ts("updated_at").notNull().defaultNow(),
});

export const session = pgTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: ts("expires_at").notNull(),
    token: text("token").notNull().unique(),
    createdAt: ts("created_at").notNull().defaultNow(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
    /** Always null: stripped in a database hook (no IP addresses stored) */
    ipAddress: text("ip_address"),
    /** Always null: stripped in a database hook */
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (t) => [index("session_user_idx").on(t.userId)],
);

export const account = pgTable(
  "account",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    /** credential | google | discord */
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: ts("access_token_expires_at"),
    refreshTokenExpiresAt: ts("refresh_token_expires_at"),
    scope: text("scope"),
    /** Argon2id PHC string for providerId = credential */
    password: text("password"),
    createdAt: ts("created_at").notNull().defaultNow(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [index("account_user_idx").on(t.userId)],
);

export const verification = pgTable(
  "verification",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: ts("expires_at").notNull(),
    createdAt: ts("created_at").defaultNow(),
    updatedAt: ts("updated_at").defaultNow(),
  },
  (t) => [index("verification_identifier_idx").on(t.identifier)],
);

// ---------------------------------------------------------------------------
// Guests (price alerts without an account)
// ---------------------------------------------------------------------------
export const guest = pgTable("guest", {
  id: serial("id").primaryKey(),
  /** lower-case */
  email: text("email").notNull().unique(),
  createdAt: ts("created_at").notNull().defaultNow(),
  lastActiveAt: ts("last_active_at").notNull().defaultNow(),
});

/**
 * One-time / time-limited links (alert confirmation, guest management, one-click delete …).
 * Only the SHA-256 hash of the token is stored.
 */
export const accessToken = pgTable(
  "access_token",
  {
    id: serial("id").primaryKey(),
    hash: text("hash").notNull().unique(),
    /** alert_confirm | guest_manage | alert_delete | data_delete */
    kind: text("kind").notNull(),
    guestId: integer("guest_id").references(() => guest.id, { onDelete: "cascade" }),
    userId: text("user_id").references(() => user.id, { onDelete: "cascade" }),
    alertId: integer("alert_id"),
    expiresAt: ts("expires_at").notNull(),
    usedAt: ts("used_at"),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [index("access_token_expires_idx").on(t.expiresAt)],
);

// ---------------------------------------------------------------------------
// Price alerts and watchlists
// ---------------------------------------------------------------------------
export const alert = pgTable(
  "alert",
  {
    id: serial("id").primaryKey(),
    userId: text("user_id").references(() => user.id, { onDelete: "cascade" }),
    guestId: integer("guest_id").references(() => guest.id, { onDelete: "cascade" }),
    productId: integer("product_id")
      .notNull()
      .references(() => product.id, { onDelete: "cascade" }),
    /** Only shops of this country are checked */
    country: text("country").notNull(),
    /** target (desired price) | drop (every drop above a threshold) */
    kind: text("kind").notNull(),
    targetCents: integer("target_cents"),
    includeShipping: boolean("include_shipping").notNull().default(true),
    minDropPercent: real("min_drop_percent").notNull().default(3),
    minDropCents: integer("min_drop_cents").notNull().default(50),
    backInStock: boolean("back_in_stock").notNull().default(false),
    /** one daily summary instead of single messages */
    digest: boolean("digest").notNull().default(false),
    /** email | discord | push */
    channels: text("channels").array().notNull().default(sql`'{email}'::text[]`),
    /** pending (guest, not confirmed) | active | paused */
    status: text("status").notNull().default("pending"),
    confirmedAt: ts("confirmed_at"),
    lastNotifiedAt: ts("last_notified_at"),
    lastNotifiedCents: integer("last_notified_cents"),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [
    index("alert_user_idx").on(t.userId),
    index("alert_guest_idx").on(t.guestId),
    index("alert_product_country_idx").on(t.productId, t.country),
  ],
);

export const watchlist = pgTable(
  "watchlist",
  {
    id: serial("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [index("watchlist_user_idx").on(t.userId)],
);

export const watchlistItem = pgTable(
  "watchlist_item",
  {
    watchlistId: integer("watchlist_id")
      .notNull()
      .references(() => watchlist.id, { onDelete: "cascade" }),
    productId: integer("product_id")
      .notNull()
      .references(() => product.id, { onDelete: "cascade" }),
    addedAt: ts("added_at").notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.watchlistId, t.productId] })],
);
